#let benchmark_results_table() = {
  let data = bench_data()
  let meta = data.meta
  let dirty_tag = if "dirty" in meta and meta.dirty { [ · veränderter Quellbaum] } else { [] }
  let rows = benchmark_rows().map(((label, sub, wl, has_model)) => {
    let sib = bench_find(data, "sibuna", sub, wl)
    let model = none
    (
      [#label],
      [#fmt_ns(if sib != none { sib.ns_per_op_median } else { none })],
      [#fmt_ns(if sib != none { sib.ns_per_op_min } else { none }) – #fmt_ns(if sib != none { sib.ns_per_op_max } else { none })],
      [#fmt_int(if sib != none { sib.ops_per_sec } else { none })],
    )
  }).flatten()
  let naive = bench_find(data, "sibuna-naive", "bot_matcher", "sequential_substring_40_signatures")
  let ac = bench_find(data, "sibuna", "bot_matcher", "aho_corasick_40_signatures")
  [
    #text(size: 8pt, fill: gray)[
      Erfasst #meta.date · #meta.host · #meta.cpu · #meta.os · Revision
      #raw(meta.git)#dirty_tag · Zig #meta.zig · ReleaseFast · 7 Batches, Median mit Min–Max-Spanne
    ]
    #v(6pt)
    #grid(
      columns: (1fr, 1fr, 1fr, 1fr),
      gutter: 6pt,
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "pow_verify", "hashcash_16_bits").ns_per_op_median)], [Hashcash-Prüfung],
        [Hardware-SHA-256, ohne Allokation], fill: blue_light, stroke: blue),
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "token_auth", "blake3_mac_token").ns_per_op_median)], [Sitzungstoken-Prüfung],
        [BLAKE3 mit Schlüssel, 75-Zeichen-Cookie], fill: green_light, stroke: green),
      stat_tile([#calc.round(meta.idle_rss_kb / 1024, digits: 1) MiB], [Residente Speichernutzung im Leerlauf],
        [Daemon nach dem Start, Speicher aus], fill: amber_light, stroke: amber),
      stat_tile([#calc.round(meta.binary_bytes / 1048576, digits: 1) MiB], [Daemon-Binärdatei],
        [WASM-Löser: #meta.wasm_bytes Bytes], fill: rgb("f5f3ff"), stroke: rgb("7c3aed")),
    )
    #v(8pt)
    #block(width: 100%, inset: 10pt, radius: 5pt, fill: blue_light, stroke: 0.5pt + rule)[
      #text(size: 11pt, weight: "bold")[Gemessene Latenz je Operation]
      #linebreak()
      #text(size: 8pt, fill: gray)[Die Tabelle zeigt gemessene Latenzen der Grundoperationen. Allokationen werden nicht erfasst.]
      #v(5pt)
      #table(
        columns: (1.6fr, 0.8fr, 1fr, 0.8fr),
        table.header([*Arbeitslast*], [*Median*], [*Spanne*], [*ops/s*]),
        ..rows,
      )
      #v(4pt)
      #text(size: 8pt, fill: gray)[Zur Einordnung: Die sequenzielle Teilstringsuche nach denselben 40 Bot-Signaturen kostet auf diesem Host #fmt_ns(naive.ns_per_op_median). Der Automat benötigt #fmt_ns(ac.ns_per_op_median).]
    ]
  ]
}

